import java.util.*;public class Q7_Wrapper_Classes_Autoboxing{public static void main(String[]x){int n=25;Integer obj=n;int value=obj;System.out.println("Autoboxed: "+obj+" Unboxed: "+value);ArrayList<Integer>a=new ArrayList<>(Arrays.asList(10,20,30,40,50));int sum=0;for(int v:a)sum+=v;System.out.println("Values: "+a+" Sum: "+sum+" Average: "+(double)sum/a.size());int i=Integer.parseInt("123");double d=Double.parseDouble("45.67");String s=Integer.toString(i);System.out.println(i+" "+d+" "+s);}}
